with gaps as (select *, case when paid_at - lag(paid_at) over (partition by order_id order by paid_at, id) > interval '90' day then 1 else 0 end as is_new_session from payments), sessions_payments as (select *, sum(is_new_session) over (partition by order_id order by paid_at, id rows between unbounded preceding and current row) as session_no from gaps) select s.id, s.order_id, s.status, s.is_new_session, s.session_no, (select min(t2.unit_price) from order_items t2 where t2.order_id = s.order_id) as min_order_item_unit_price from sessions_payments s order by order_id nulls last, is_new_session
